{
  "bottlenecks": [
    {
      "id": "fusion",
      "category": "fusion",
      "evidence": "Incumbent uses separate softmax_stats and softmax_apply kernels (fused=false), causing overhead from multiple kernel launches and intermediate memory traffic. Library baseline with fused kernel runs ~3x faster.",
      "uncertainty": "Low",
      "rationale": "Fusion combines reduction and application in one kernel, reducing launch overhead and intermediate storage traffic, which is critical given the measured ~3x speedup in baseline."
    },
    {
      "id": "launch",
      "category": "launch",
      "evidence": "Multiple small kernel launches from separate stats and apply passes increase launch overhead, contributing to reduced throughput.",
      "uncertainty": "Medium",
      "rationale": "Launch overhead is non-trivial especially for irregular small tiles and many kernels; fusion reduces number of launches, improving efficiency."
    },
    {
      "id": "masking",
      "category": "masking",
      "evidence": "Shape irregularity (513 x 781) causes masking overhead due to partial tiles, increasing computation and load/store inefficiency.",
      "uncertainty": "Medium",
      "rationale": "Masking partial tiles wastes work and can reduce utilization; tuning block sizes to better fit irregular shapes can reduce masking overhead."
    },
    {
      "id": "resources",
      "category": "resources",
      "evidence": "Incumbent kernel uses moderate registers per thread (17-21) and shared memory (0-16 bytes) with no spills, no occupancy bottleneck claims.",
      "uncertainty": "High",
      "rationale": "Resource use is moderate with no spills or occupancy issues detected, so unlikely to be a bottleneck."
    },
    {
      "id": "memory",
      "category": "memory",
      "evidence": "Logical minimum traffic is measured but no direct DRAM traffic or coalescing metrics; strides and layout unknown.",
      "uncertainty": "High",
      "rationale": "Memory coalescing impact uncertain but likely minor compared to fusion and launch overheads."
    }
  ]
